import { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { db } from "../../config/firebaseConfig"; // Импортиране на Firebase конфигурацията
import { doc, getDoc, updateDoc } from "firebase/firestore"; // Firebase функции за обновяване на документи

export default function UpdateProject() {
    const navigate = useNavigate();
    const { projectId } = useParams(); // Получаваме projectId от URL параметъра
    const [project, setProject] = useState(null); // Стейт за проектните данни

    // Извличаме съществуващите данни за проекта
    useEffect(() => {
        const fetchProjectDetails = async () => {
            try {
                const projectRef = doc(db, "projects", projectId);
                const projectSnap = await getDoc(projectRef);

                if (projectSnap.exists()) {
                    setProject(projectSnap.data());
                } else {
                    alert("Project not found!");
                    navigate("/admin/projects");
                }
            } catch (error) {
                console.error("Error fetching project details:", error);
                alert("Failed to fetch project details.");
            }
        };

        fetchProjectDetails();
    }, [projectId, navigate]);

    // Обработчик за изпращане на формата
    const updateHandler = async (e) => {
        e.preventDefault();

        // Вземаме данните от формуляра
        let formData = new FormData(e.currentTarget);
        let { title, subtitle, description, gitLink, img } = Object.fromEntries(formData);

        // Актуализираме данните в Firestore
        try {
            const projectRef = doc(db, "projects", projectId);

            await updateDoc(projectRef, {
                title,
                subtitle,
                description,
                gitLink,
                img
            });

            alert('The project was updated successfully!');
            navigate('/admin/projects');
        } catch (error) {
            console.error("Error updating project:", error);
            alert("Failed to update the project. Please try again.");
        }

        e.target.reset(); // Рестартираме формуляра
    };

    if (!project) {
        return <p>Loading project details...</p>; // Ако данните все още се зареждат, показваме това съобщение
    }

    return (
        <section id="admin">
            <div className="content">
                <h2>Update Project</h2>
                <form onSubmit={updateHandler}>
                    <label htmlFor="title">Title:</label>
                    <input type="text" id="title" name="title" defaultValue={project.title} required />

                    <label htmlFor="subtitle">Subtitle:</label>
                    <input type="text" id="subtitle" name="subtitle" defaultValue={project.subtitle} required />

                    <label htmlFor="description">Description:</label>
                    <input type="text" id="description" name="description" defaultValue={project.description} required />

                    <label htmlFor="gitLink">GitHub Link:</label>
                    <input type="text" id="gitLink" name="gitLink" defaultValue={project.gitLink} required />

                    <label htmlFor="img">Image:</label>
                    <input type="text" id="img" name="img" defaultValue={project.img} required />

                    <input type="submit" value="Update" />
                </form>
            </div>
        </section>
    );
}
